Plan:
1. Use the active sheet, treat row 2 as the header row, and collect data columns to the left of the answer column H.
2. For each answer row 3–5, find the first column with the maximum numeric value and write its header into H.
3. Save the workbook with plain values in H3:H5.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

answer_col = 8          # H
header_row = 2
answer_rows = range(3, 6)  # H3:H5

def as_number(value):
    if isinstance(value, bool):
        return float(value)
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None

data_cols = []
for col in range(1, answer_col):
    header = vws.cell(row=header_row, column=col).value
    if header is not None and str(header).strip() != "":
        data_cols.append(col)

print("Data columns:", data_cols)

for row in answer_rows:
    best_value = None
    best_header = None

    for col in data_cols:
        value = as_number(vws.cell(row=row, column=col).value)
        if value is None:
            continue

        if best_value is None or value > best_value:
            best_value = value
            best_header = vws.cell(row=header_row, column=col).value

    if best_header is not None:
        if isinstance(best_header, str):
            best_header = best_header.strip()
        ws.cell(row=row, column=answer_col).value = best_header
    else:
        ws.cell(row=row, column=answer_col).value = None

    print(f"Row {row}: {best_header}")

wb.save(OUT)
